INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('blocksy-theme','products','Blocksy Theme','A versatile WordPress theme known for its flexibility and customization options','https://creativethemes.com/blocksy/','https://creativethemes.com/blocksy/wp-content/uploads/2022/06/home-hero-demo-1.jpg','img/blocksy-theme.jpg','WordPress','Blocksy is a lightweight and highly customizable WordPress theme that works smoothly with major page builders and the block editor. It gives you extensive header, footer, and layout controls plus performance-focused defaults for building almost any kind of site. This lifetime deal unlocks the premium features for a single upfront payment instead of an annual renewal.','Flexible, fast, deeply customizable WordPress theme','https://creativethemes.com/blocksy/pricing/',NULL,0,'[{"label":"Personal (1 site) Lifetime","features":["~$199 one-time lifetime license","1 site/license","Core set of Blocksy Pro extensions","Lifetime updates & support"]},{"label":"Professional (up to 10 sites) Lifetime","features":["~$299 one-time lifetime license","Up to 10 licenses","Full Blocksy Pro experience: all extensions incl. Shop Extra, Post Types Extra","Lifetime updates & support"]},{"label":"Agency (unlimited sites) Lifetime","features":["~$499 one-time lifetime license","Unlimited licenses/sites","All Pro extensions plus exclusive White Label extension","Lifetime updates & support"]}]',NULL,'["Fast, lightweight WordPress theme with a powerful native customizer and header/footer builder","Agency lifetime tier unlocks unlimited sites plus the exclusive White Label extension","Full extension set (Shop Extra, Post Types Extra, White Label) on the top tiers","Deep integration with Gutenberg, Elementor, Bricks and WooCommerce"]',5,'2026-09-15T19:42:42.949Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('blocksy-theme',0,'sold','fixed',345,'Agency LTD Plan');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('blogely','products','Blogely','A comprehensive content creation and management platform that may help in planning - Professional LTD','https://blogely.com/plans/','https://blogely.com/wp-content/uploads/brizy/imgs/blogely-logo-original-146x26x0x0x146x26x1685905764.png','img/blogely.png','Content','Blogely is an all-in-one content workspace where you research, write, organize assets, optimize for SEO, and publish from one place. It pairs a block-based writing app with editorial planning, SEO scoring, and one-click WordPress publishing to keep your whole content workflow tidy. As a lifetime deal it''s a one-time payment covering the content tools a creator or team uses daily.','Plan, write, and publish content together','https://appsumo.com/products/blogely/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Blogely2x_zZFzWRk.jpg',0,'[{"label":"License Tier 1 (1 code)","features":["2 portfolios","1 website","20 research docs/mo","16 articles/mo"]},{"label":"License Tier 2 (2 codes)","features":["4 portfolios","6 websites","80 research docs/mo","Unlimited articles","120 SEO credits","1 team seat"]},{"label":"License Tier 3 (3+ codes)","features":["10 portfolios","20 websites","150 research docs/mo","Unlimited articles","250 SEO credits","3 team seats"]}]','{"rating":"4.69","count":"97"}','["Unified research hub: top 100 SERP results in seconds","Built-in SEO analysis, keywords, and competition heatmaps","Workflow automation with team assignment and deadlines","Content marketplace to buy/sell articles or hire freelancers"]',6,'2026-09-15T19:42:42.949Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('blogely',0,'available','fixed',95,'Appsumo 3 Codes');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('bricks-builder','products','Bricks Builder','An innovative, visual site builder for WordPress.','https://bricksbuilder.io/','https://bricksbuilder.io/wp-content/uploads/2026/06/social-share.jpg','img/bricks-builder.jpg','WordPress','Bricks is a visual, performance-oriented site builder for WordPress that lets you design full websites on a live canvas with fine control over markup and styling. It''s popular with developers and agencies for its clean output, dynamic data, and flexible layout tools. This lifetime deal gives you the builder and future updates for one upfront payment rather than a yearly license.','Visual site builder for WordPress pros','https://bricksbuilder.io/pricing/','https://bricksbuilder.io/wp-content/uploads/2023/07/bricks-logo.svg',0,'[{"label":"Starter (1 site)","features":["$79/year","1 website","All features, updates & support"]},{"label":"Business (3 sites)","features":["$149/year","3 websites","All features, updates & support"]},{"label":"Agency (unlimited)","features":["$249/year","Unlimited websites","All features + Expert listing eligibility"]},{"label":"Ultimate Lifetime (unlimited)","features":["$599 one-time","Unlimited websites","All future updates, features & support","Expert listing eligibility"]}]',NULL,'["Visual, performance-focused WordPress site builder (theme + builder in one)","Owned Ultimate LTD = one-time $599 for unlimited sites with all future updates","110+ elements plus Query Loop, Menu, Popup and WooCommerce builders","Conditions & Interactions, community templates, local/staging sites don''t count against license"]',7,'2026-09-15T19:42:42.949Z');
