INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('css-hero','products','Css Hero','A powerful plugin to easily customize the look of your WordPress site with an intuitive point-and-click interface /animator','https://www.csshero.org/','https://i.imgur.com/XcjopWP.png','img/css-hero.png','WordPress','CSS Hero lets you restyle your WordPress site visually with a point-and-click interface, adjusting fonts, colors, spacing, and more without writing CSS. It works across most themes and shows changes live so you can fine-tune your design in real time. This lifetime deal gives you the customization tool for a single payment instead of a recurring license.','Point-and-click styling for any WordPress site','https://www.csshero.org/buy-now/',NULL,0,'[{"label":"Starter (1 site)","features":["$29/year","Single site","Full visual CSS editor functionality"]},{"label":"Personal (up to 5 sites)","features":["$59/year","Up to 5 sites","Full functionality"]},{"label":"Professional (up to 999 sites)","features":["$199/year","Up to 999 sites","Full functionality"]},{"label":"Lifetime Pro w/ Animator (up to 999 sites)","features":["$599 one-time (often discounted to ~$249)","Up to 999 sites + Multisite support","Includes CSS Hero + Animator plugins","Lifetime access, one-time payment"]}]',NULL,'["Visual, no-code live CSS editor that customizes any WordPress theme or plugin (Divi, Elementor, Beaver Builder, Genesis)","Owned Lifetime deal bundles the Animator plugin for code-free animations","Lifetime Pro covers up to 999 sites plus Multisite","30-day money-back guarantee"]',9,'2026-09-15T19:42:42.949Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('css-hero',0,'available','fixed',395,'CSS Hero LTD w/ animator');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('dynamic-ooo','products','Dynamic.ooo','Enhances your WordPress website with dynamic content capabilities','https://www.dynamic.ooo/','https://u9m4v4n3.delivery.rocketcdn.me/wp-content/uploads/2023/03/dynamic-content-for-elementor-banner-1024x410.jpg','img/dynamic-ooo.jpg','WordPress','Dynamic.ooo (Dynamic Content for Elementor) adds a large set of advanced widgets, dynamic data connections, and display logic to the Elementor page builder, no code required. It helps you build data-driven, highly customized WordPress sites with more design flexibility than Elementor offers alone. As a lifetime deal, you pay once for the extension and its capabilities instead of renewing every year.','Supercharge Elementor with dynamic content','https://www.dynamic.ooo/dynamic-content-for-elementor/pricing',NULL,0,'[{"label":"Starter (annual)","features":["~EUR 19/year","Annual license","All widgets & modules, support and updates"]},{"label":"Enterprise (annual)","features":["~EUR 39/year","Annual license","All widgets & modules"]},{"label":"Lifetime Personal (1 site)","features":["One-time lifetime license","1 site","All widgets & extensions, lifetime updates","Annual support billed separately/optionally"]},{"label":"Lifetime Professional (up to 1000 sites)","features":["One-time lifetime license","Up to 1000 sites","All widgets & extensions, lifetime updates"]}]',NULL,'["Elementor add-on with 80+ widgets and 45+ extensions focused on dynamic data","Owned LTD Elementor tier = one-time lifetime license (updates included for life of product)","Extends Elementor Pro forms with conditional/REGEX fields, payment processors and PDF generation","Conditional display options and content Views; 30-day money-back guarantee"]',10,'2026-09-15T19:42:42.949Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('dynamic-ooo',0,'sold','fixed',193,'LTD Elementor');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('easynote','products','Easynote','Project management tool designed to help teams organize work and manage projects and tasks efficiently.','https://easynote.com','https://easynote.com/wp-content/uploads/2020/12/easynote-easyview.png','img/easynote.png','Project Management','Easynote is an all-in-one work management platform that brings projects, tasks, calendars, documents and files together so your team stops switching between tools. It is built to be easy to pick up, making it a practical alternative to heavier apps like Asana or ClickUp. With this lifetime deal you get ongoing access for a single one-time payment instead of a recurring subscription.','Organize projects and teamwork in one place','https://appsumo.com/products/easynote/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Easynote.png',0,'[{"label":"Tier 1","features":["7 team members","50 GB storage","Unlimited tasks, projects, conversations, categories","Unlimited guests","Lifetime access"]},{"label":"Tier 2","features":["15 team members","150 GB storage","Unlimited tasks, projects, conversations, categories","Unlimited guests","Lifetime access"]},{"label":"Tier 3","features":["30 team members","300 GB storage","Unlimited tasks, projects, conversations, categories","Unlimited guests","Lifetime access"]}]','{"rating":"5","count":"12"}','["Organize any workload intuitively in a scalable and collaborative platform","Easyview grid-based task visualization","Anysearch built-in search across documents and attachments","Kanban boards, customizable dashboards, templates","Recurring tasks, file uploads, two-factor authentication, Excel/PDF export"]',11,'2026-09-15T19:42:42.949Z');
