INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('encharge-email','products','Encharge Email','Nurture, convert, and onboard customers with advanced behavior emails  (*Email not changeable)','https://encharge.io','https://i.imgur.com/vOJAP5H.png','img/encharge-email.png','Email','Encharge is a marketing automation platform that lets you build email flows triggered by what users actually do in your product or on your site. With a visual flow builder, segmentation and integrations for tools like Stripe and HubSpot, it helps you onboard, nurture and convert customers automatically. This lifetime deal gives you that automation for a one-time payment instead of a monthly bill.','Behavior-based email automation for SaaS','https://appsumo.com/products/encharge/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Encharge_-_16_9_uuid_c5865978-ab9a-407f-b580-85334763fb30.png',0,'[{"label":"Tier 1 ($119)","features":["5,000 subscribers","0 sub-accounts","Core automation","Unlimited emails, flow builder, team members, native forms, behavior-based automation"]},{"label":"Tier 2 ($239)","features":["10,000 subscribers","3 sub-accounts","Enhanced features"]},{"label":"Tier 3 ($359)","features":["15,000 subscribers","6 sub-accounts","Advanced segmentation"]},{"label":"Tier 4 ($479)","features":["20,000 subscribers","9 sub-accounts"]},{"label":"Tier 5 ($599)","features":["Higher subscriber capacity"]},{"label":"Tier 6 ($1,199)","features":["50,000 subscribers","Native Shopify/WooCommerce integrations","Whitelabel branding removal"]}]','{"rating":"4.71","count":"348"}','["Automate email marketing with a drag-and-drop flow builder and segmentation","Visual workflow mapping without coding","Behavior-triggered automation and dynamic audience segmentation","A/B testing for subject lines and campaigns","Native integrations: Calendly, Stripe, Facebook Ads, Zapier"]',14,'2026-09-15T19:42:42.949Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('encharge-email',0,'sold','na',NULL,'License Tier 5');
