INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('getformly','products','Getformly','Formly - Forms & Surveys (Typeform/Jotform alternative)','https://www.getformly.com','https://static.wixstatic.com/media/370223_9c2ea2a99f244110b171c13d2f100d78~mv2.png','img/getformly.png','Forms & Surveys','Formly is a no-code form builder for creating polished forms, surveys and quizzes with a drag-and-drop editor and ready-made templates. It supports conditional logic, multi-page forms, payment collection and live result charts, making it a solid alternative to Typeform or Jotform. This lifetime deal lets you build unlimited branded forms for a single one-time payment.','Build interactive forms, surveys and quizzes','https://appsumo.com/products/formly-forms-surveys-quizzes/','https://appsumo2-cdn.appsumo.com/media/deals/images/New_First_Image.png',0,'[{"label":"Plan 1 ($99)","features":["1 user","Unlimited forms","Unlimited responses","50 AI forms","5 domains","5 workspaces","5 GB storage"]},{"label":"Plan 2 ($198)","features":["3 users","Unlimited forms/responses","100 AI forms","10 domains","10 workspaces","10 GB storage"]},{"label":"Plan 3 ($297)","features":["5 users","Unlimited forms/responses","200 AI forms","Unlimited domains","Unlimited workspaces","25 GB storage"]},{"label":"Plan 4 ($396)","features":["7 users","Unlimited forms/responses","500 AI forms","Unlimited domains","Unlimited workspaces","50 GB storage"]}]','{"rating":"4.61","count":"233"}','["Create branded forms, surveys, and quizzes with logic and personalized charts—powered by AI","Conditional logic and branching for dynamic question flows","Live chart visualization (bar, donut, radar, gauge)","Stripe payment collection integration","Support for 25+ languages including RTL"]',17,'2026-09-15T19:42:42.949Z');
