INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('orderable','products','Orderable','Take restaurant orders online with Orderable. The WordPress plugin designed to help you manage your restaurant website your way.','https://orderable.com','https://i.imgur.com/HxdwGqy.png','img/orderable.png','E-commerce','Orderable is a WordPress plugin that adds a full online ordering system to your restaurant, bakery, or takeaway website, letting customers order directly without per-order transaction fees. You control menus, order timing, and delivery or pickup right from your own site. Grab it as a one-time lifetime deal and keep taking orders without a monthly subscription.','Take restaurant orders on WordPress','https://orderable.com/pricing/','https://orderable.com/wp-content/uploads/2025/01/online-takeaway-ordering-system.svg',0,'[{"label":"Free","features":["Online ordering menu with zero transaction fees","Delivery/pickup date slots, ASAP option, lead time & preorder days","Live order view, mobile-friendly ordering, receipt printing","Automated reminder emails"]},{"label":"Pro - $149/yr (1 site)","features":["Everything in Free plus 1 year updates & support","Delivery/pickup time slots, table ordering via QR codes","Multiple store locations, product add-ons, order bumps","Custom checkout & tipping, custom order statuses/notifications","Dietary/allergen labels, nutritional info, order caps","SMS/WhatsApp/Email notifications, floating cart widget"]}]',NULL,'["WooCommerce restaurant/takeaway online-ordering plugin","Owner''s plan is ''LTD 25 Sites'' - the current vendor site no longer sells a lifetime tier (only annual Pro at $149/yr for 1 site), so the LTD is a legacy deal","30-day money-back guarantee"]',33,'2026-09-15T19:42:42.949Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('orderable',0,'available','fixed',375,'LTD 25 Sites');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('oxygenbuilder','products','Oxygenbuilder','A powerful website builder for WordPress that offers visual editing with drag-and-drop functionality','https://oxygenbuilder.com/pricing/','https://oxygenbuilder.com/wp-content/uploads/2025/01/cover-placeholder.jpg','img/oxygenbuilder.jpg','WordPress','Oxygen is a developer-friendly visual website builder for WordPress that gives you drag-and-drop control while outputting clean, lightweight code. It replaces bloated page builders so you can design entire sites, headers, and templates exactly the way you want. A lifetime license means one payment for ongoing access instead of recurring builder fees.','Visual website building for WordPress','https://oxygenbuilder.com/pricing/',NULL,0,'[{"label":"Basic - $129 lifetime (unlimited sites)","features":["Visual site builder","Gutenberg block builder","Simplified client UI","Composite elements","WooCommerce integration"]},{"label":"WooCommerce - $149 lifetime (unlimited sites)","features":["All Basic features","Enhanced/advanced WooCommerce integration"]},{"label":"Ultimate (Ultimate LTD) - $179 lifetime (unlimited sites)","features":["All Oxygen features included","Everything in Basic + WooCommerce","Full premium add-on set","Use on unlimited personal and client sites with no recurring fees"]},{"label":"Lifetime Bundle - $199.50 launch (future $399.99)","features":["Oxygen Classic + Oxygen 6","Three premium add-ons: Breakdance Elements, WooCommerce, Forms","Unlimited sites, one-time payment"]}]',NULL,'["WordPress visual site builder - all tiers are true lifetime licenses with no recurring fees and unlimited sites","Owner holds the Ultimate LTD tier ($179 lifetime) which includes all Oxygen features","Usable on client websites without extra licensing; 60-day money-back guarantee","57,000+ customers / 180,000+ websites"]',34,'2026-09-15T19:42:42.949Z');
