INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('plutio','products','Plutio','A business management tool that combines project management, and much, much more','https://www.plutio.com/pricing','https://plutio.com/static/images/meta/meta_image.jpg','img/plutio.jpg','Project Management','Plutio brings projects, tasks, proposals, invoices, contracts, forms, and client messaging together in a single workspace, so freelancers and small teams can stop juggling separate tools. Everything a client project needs, from first proposal to final invoice, lives in one place. This lifetime deal lets you replace several monthly subscriptions with a single one-time payment.','Run your whole business in one app','https://appsumo.com/products/plutio/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Plutio_ZquJ1EN.jpg',0,'[{"label":"1 Code","features":["Lifetime access","5 teammates","All Team Plan features"]},{"label":"2 Codes","features":["Lifetime access","10 teammates","All Team Plan features"]},{"label":"3 Codes","features":["Lifetime access","15 teammates","All Team Plan features"]}]','{"rating":"4.64","count":"197"}','["Manage projects, communicate with clients, share files, create proposals, send invoices, and get paid—all from one app","Unlimited projects and clients","Client portal included","White-label capabilities (requires 4 codes for new purchasers; 2 codes for previous 2017-2019 buyers)","GDPR compliant"]',35,'2026-09-15T19:42:42.949Z');
