INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('wp-stackable','products','WP Stackable','A Gutenberg blocks plugin for WordPress that provides additional blocks and options to enhance page building capabilities.','https://wpstackable.com','https://wpstackable.com/wp-content/uploads/2025/03/website-share.webp','img/wp-stackable.webp','WordPress','Stackable extends the WordPress block editor with a large library of custom Gutenberg blocks, a global design system, and layout tools for building pages without code. It''s lightweight and works alongside your theme, making it easy to design polished, responsive pages directly in the native editor. The lifetime deal gets you the premium blocks and features for a single upfront payment.','Powerful Gutenberg blocks for faster sites','https://appsumo.com/products/stackable/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-Header-Stackable-16_9.png',0,'[{"label":"1 Code - $69","features":["3 websites","44 custom blocks","Page builder-like options","Smart copy/paste styles","Global design system","Global color schemes","Advanced responsiveness","Flexbox layout"]},{"label":"2 Codes - $138","features":["10 websites","Same features as Tier 1"]},{"label":"3 Codes - $207","features":["50 websites","Same features as Tier 1"]},{"label":"4 Codes - $276","features":["Unlimited websites","Same features as Tier 1"]}]','{"rating":"4.87","count":"53"}','["44 custom blocks for comprehensive site building","350+ ready-made layouts to accelerate design workflow","Global design system for consistent styling across sites","Dynamic content and advanced responsiveness controls","Motion effects, animations, and lightbox capabilities"]',59,'2026-09-15T19:42:42.950Z');
