INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('wp-statistics','products','WP-Statistics','A plugin for WordPress that provides comprehensive analytics and statistics without the need for external services.','https://wp-statistics.com','https://wp-statistics.com/wp-content/uploads/2024/11/opengraph_Thumbnail_wp_statistics.png','img/wp-statistics.png','Analytics','WP Statistics is a self-hosted, privacy-focused analytics plugin that tracks visitors, content performance, and traffic sources without cookies or external services. Because your data stays on your own server, it helps you stay compliant with privacy regulations while still understanding your audience. With this lifetime deal you get premium analytics for a one-time payment.','Privacy-focused analytics for WordPress','https://wp-statistics.com/pricing/','https://wp-statistics.com/wp-content/themes/wp-statistics.com/assets/img/logo.svg',0,'[{"label":"Free ($0/yr, unlimited sites)","features":["Unlimited page-views & visitors","Content & category analytics","Online / visitor analytics","Cookie-less tracking","Traffic-source, geo & device reports","GDPR-ready privacy toolkit","Visitor journey & role-based access","Email & community support"]},{"label":"Premium — Single Site ($119/yr)","features":["Everything in Free","Priority support","Custom post types & taxonomy analytics","Real-time live visitors feed","Author analytics","Google Search Console integration","Campaign (UTM) analytics","Custom events & goal reports"]},{"label":"Premium — Up to 5 Sites ($249/yr)","features":["All Premium features across up to 5 sites"]},{"label":"Premium — Unlimited ($449/yr, Best Value)","features":["All Premium features across unlimited sites (up to 100 under fair-usage)"]}]',NULL,'["Privacy-first, cookie-less WordPress analytics","GDPR-ready, self-hosted (data stays in your DB)","Trusted by 600,000+ websites","14-day money-back guarantee"]',60,'2026-09-15T19:42:42.950Z');
