INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('wp301redirects','products','WP301redirects','A plugin designed to manage and implement 301 redirects in WordPress','https://wp301redirects.com','https://wp301redirects.com/wp-content/uploads/2019/10/cropped-wp-301-redirects-icon-v2-270x270.png','img/wp301redirects.png','SEO','WP 301 Redirects helps you manage 301 redirects, catch 404 errors, and monitor broken or risky outgoing links so you can preserve your SEO and keep visitors on track. It logs redirect activity and includes tools handy for rebranding and agency work. Pick up the lifetime deal to handle your site''s redirects with a single payment instead of a subscription.','Fix redirects, 404s, and broken links','https://appsumo.com/products/wp-301-redirects/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-301ReDirects.jpg',0,'[{"label":"License Tier 1 - $49 (was $158)","features":["20 sites","5 full site scans per month","White labeling","License & site manager","Remote site control","Stats","Lifetime access","60-day refund guarantee"]}]','{"rating":"4.85","count":"281"}','["Broken Link Recovery: visitors who mistype URLs get redirected instead of landing on 404s","Smart Detection: set up automatic redirect rules with adjustable typo sensitivity","Link Scanning: identifies broken URLs and harmful outlinks using Google Safe Browsing and Alexa Rank API","Centralized Dashboard: track redirects, 404 errors, browser data, and export PDF reports"]',61,'2026-09-15T19:42:42.950Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('wp301redirects',0,'sold','fixed',45,'');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('wpcompress','products','WPcompress','A WordPress plugin that optimizes images and scripts to reduce website load times and improve performance.','https://wpcompress.com','https://ps.w.org/wp-compress-image-optimizer/assets/banner-1544x500.jpg','img/wpcompress.jpg','WordPress','WP Compress optimizes images and assets to reduce page weight and improve WordPress load times, with bulk compression, WebP conversion, and automatic optimization of new uploads. Its adaptive modes serve appropriately sized media based on the visitor''s device and connection to keep pages fast. The lifetime deal gives you these performance tools for one upfront payment.','Speed up sites with smart optimization','https://wpcompress.com/pricing/','https://cdn.wpcompress.com/q:i/r:0/wp:1/w:1/u:https://wpcompress.com/wp-content/uploads/2024/03/speed-two-columns.webp?v=9d9aee86af',0,'[{"label":"1 Site ($9/mo)","features":["Unlimited optimization — no credits, overages or metering","Advanced caching & critical CSS","Image optimization (AVIF/WebP)","Lazy-loading & deferred JavaScript","Optional premium global CDN","One-click setup, 24/7 monitoring"]},{"label":"3 Sites ($19/mo)","features":["All optimization features across 3 sites"]},{"label":"Unlimited ($49/mo, Most Popular)","features":["All optimization features across unlimited sites"]},{"label":"Whitelabel Agency ($99/mo)","features":["Unlimited sites","White-label branding","Remote website management portal","Agency client management"]}]','{"rating":"4.9","count":"50,000+ sites & agencies"}','["Adaptive image compression with local WebP creation","Global CDN up to 123 edge locations, 95% cache hit ratio","WordPress plugin plus universal non-WordPress version","Rated 4.9 by 50,000+ sites","60-day money-back guarantee"]',62,'2026-09-15T19:42:42.950Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('wpcompress',0,'sold','fixed',240,'');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('wpreset','products','WPReset','A plugin that helps quickly reset the database of a WordPress site to the default installation state without modifying files.','https://wpreset.com','https://wpreset.com/wp-content/uploads/2018/06/wp-reset-coder-at-work.png','img/wpreset.png','WordPress','WP Reset is a development and recovery toolkit that lets you reset your WordPress site, create snapshots as restore points, and roll back changes with one click. It includes an emergency recovery tool, cleanup utilities, and plugin/theme collections that make testing and rebuilding sites much faster. This lifetime deal covers it with a single payment rather than a recurring fee.','Reset, recover, and manage WordPress sites','https://appsumo.com/products/wp-reset/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-WP_Reset_xl08uy1_uuid_ad3964a8-5aa9-46ea-8ffb-fc42ab5df930.png',0,'[{"label":"License Tier 1 - $49 (was $158)","features":["5 site licenses","5 cloud licenses","3 GB storage per site","White labeling","25+ tools","Snapshots","Collections","Emergency recovery script"]},{"label":"License Tier 2 - $129 (was $316)","features":["50 site licenses","15 cloud licenses","3 GB storage per site","All Tier 1 features","Remote actions/stats","Full rebranding","Staging environment"]},{"label":"License Tier 3 - $299 (was $474)","features":["Unlimited site licenses","30 cloud licenses","3 GB storage per site","All Tier 2 features"]}]','{"rating":"4.93","count":"1311"}','["Instantly reset or delete sections of WordPress sites without reinstalling","Create plugin/theme Collections for bulk installations across sites","Automated snapshots with multi-cloud storage support (WP Reset Cloud, Dropbox, Google Drive, pCloud)","Emergency Recovery Script providing 12+ tools for critical site failures","Centralized dashboard managing multiple sites and licenses"]',63,'2026-09-15T19:42:42.950Z');
