INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('be-live','inventory','Be.Live','','https://be.live/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Be.Live_eadKv4r.jpg?width=800&height=450&aspect_ratio=16:9','img/be-live.jpg','Video & Audio','Be.Live is a browser-based live streaming studio that lets you broadcast to Facebook, YouTube, LinkedIn and 40+ RTMP destinations at once, with on-screen branding, overlays, lower-thirds and guest hosting. No heavy software to install and no editing skills required. This is a transferable lifetime-deal license the owner still uses but is happy to part with for a fair offer, so send an inquiry if it fits your workflow.','Browser-based multistreaming to every platform','https://be.live/packages','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Be.Live_eadKv4r.jpg?width=800&height=450&aspect_ratio=16:9',1,'[{"label":"Starter (~$15.83/mo billed annually)","features":["Broadcast to up to 3 destinations simultaneously (YouTube, Facebook, LinkedIn, Amazon Live, RTMP)","Multiple hosts & guests","Branded overlays, logos, backgrounds","Lower thirds, countdown timers, CTA buttons"]},{"label":"Pro (~$24.16/mo billed annually)","features":["More simultaneous multistream destinations","All Starter branding & on-screen widgets","Up to 8 guests/hosts on stream","AI Comment Assistant"]},{"label":"Growth (~$38.33/mo billed annually)","features":["Highest multistream destination limits","All Pro features","Full branding & engagement toolset"]}]','{"rating":"4.1","count":"136"}','["Owner holds a legacy AppSumo Tier 3 account (3 codes stacked) — top LTD tier","Multistream to YouTube, Facebook, LinkedIn, Amazon Live & RTMP","Up to 8 guests/hosts, branded overlays, lower thirds, CTAs, tickers","AI Comment Assistant for on-screen engagement"]',65,'2026-09-15T19:42:42.950Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('be-live',0,'available','inquire',NULL,'Tier 3 account · 3 codes stacked');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('brizy-design-kit','inventory','Brizy Design Kit','','https://www.brizy.io/','https://cloud-1de12d.becdn.net/media/iW=1200&iH=630/fbd5489ab0bf9b66dc23814e285726a3.jpg','img/brizy-design-kit.jpg','Design','The Brizy Design Kit is a large library of professionally crafted, drag-and-drop blocks and sections that let you assemble polished websites and landing pages in minutes inside the Brizy builder. It is a genuine head start for anyone who wants great-looking pages without designing from scratch. The license here is a transferable lifetime deal, and while the owner has gotten good use from it, they''re open to a reasonable offer, so reach out to inquire.','Hundreds of ready-made website blocks','https://appsumo.com/products/brizy-design-kit/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-BrizyDesignKit.jpg?width=1200&quality=80&optimizer=gif',1,'[{"label":"Single tier (Lifetime access, non-stackable)","features":["250+ design blocks across nine page categories","All images and icons included","Sketch, Figma, InVision Studio compatibility","Assets approved for personal and commercial use","60-day refund window"]}]','{"rating":"3.67","count":"21"}','["Choose from nine page categories and 250+ blocks to set up your site in no time","Customizing the typography and color schemes is fast and simple","All kit assets are approved for personal and commercial use","Compatible with Sketch, InVision Studio, and Figma"]',66,'2026-09-15T19:42:42.950Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('brizy-design-kit',0,'available','inquire',NULL,'Tier 1 account');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('burner-mail','inventory','Burner Mail','','https://burnermail.io/','https://burnermail.io/assets/burnermail_og_fb_image-f475393f0a0f7d82f827e00090b4b8379b66dd3003d25e8998035be8e48aced1.png','img/burner-mail.png','Security','Burner Mail generates a unique, anonymous email alias for every service you sign up with, forwarding messages to your real inbox while shielding your identity from trackers and spam. When an alias gets abused, you simply burn it and move on, keeping your primary address clean. This is a transferable lifetime-deal license; the owner still finds it handy but will let it go for the right offer, so send an inquiry.','Disposable email aliases that guard privacy','https://burnermail.io/','https://burnermail.io/assets/how_it_works-ed9dea0e2efb9b8bfae5613b789405a331856cde97c1db1b792bd6f6505c478a.svg',1,'[{"label":"Free (being phased out)","features":["Limited number of burner email addresses","Email forwarding to personal inbox","Browser extension"]},{"label":"Premium (paid) — owner holds legacy AppSumo Tier 1 account","features":["Unlimited / higher burner address limits","Block specific senders to stop spam","Reply from burner addresses to stay anonymous","Multiple recipient management per burner","Chrome & Firefox extension","Burner management in web app & extension"]}]','{"rating":"5","count":"373,200+ users"}','["Generate unique burner email addresses for every signup","Forward, reply & block — protect your real inbox","Chrome & Firefox browser extensions","Trusted by 373,200+ users","Owner holds a legacy AppSumo Tier 1 lifetime account"]',67,'2026-09-15T19:42:42.950Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('burner-mail',0,'available','inquire',NULL,'Tier 1 account');
