INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('crello',0,'available','inquire',NULL,'Tier 1 account');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('cromojo','inventory','Cromojo','','https://cromojo.com/','https://cdn.prod.website-files.com/689c02bd6668b47b0f6a2991/6a61656809a38d01e4376b7c_cromojo-og.png','img/cromojo.png','Analytics','Cromojo is an all-in-one website growth platform that combines real-time and revenue attribution analytics, automated search-engine indexing, and uptime and issue monitoring in a single dashboard. It''s built to show marketers what actually drives revenue while keeping pages indexed and online. The license is a transferable lifetime deal, and although the owner still uses it, they''ll consider a fair offer, so send an inquiry.','Revenue-first analytics and site monitoring','https://appsumo.com/products/url-monitor/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-URLMonitor-_16_9_uuid_d372e59b-e9e0-4e01-b958-bb33348983d4.png',1,'[{"label":"License Tier 1","features":["Lifetime access","5 websites","500 pages/day"]},{"label":"License Tier 2","features":["Lifetime access","20 websites","1,200 pages/day"]},{"label":"License Tier 3","features":["Lifetime access","50 websites","2,000 pages/day","White-labeled dashboard and reports"]}]','{"rating":"3.7","count":"63"}','["Daily URL monitoring and bulk indexing","Google and Bing indexing support","Automatic indexing capability","Sitemap synchronization","Manual page addition"]',70,'2026-09-15T19:42:42.950Z');
