INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('depositphotos','inventory','Depositphotos','','https://depositphotos.com','https://static.depositphotos.com/storage/image/f5ada1b156989865f95747765191584720d82af2.jpg','img/depositphotos.jpg','Stock Media','Depositphotos is a huge royalty-free marketplace of stock photos, vector images, videos and music for your creative and commercial projects. This is a transferable lifetime-deal license, so you get ongoing access without the recurring subscription. The owner still uses it but is open to a fair offer, so reach out to inquire.','Royalty-free photos, video and music','https://appsumo.com/products/depositphotos/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-Header-DepositPhotos-16_9.png',1,'[{"label":"1 Code","features":["100 one-time AI credits","100 one-time image/vector/video/audio credits","Lifetime access","Credits never expire"]},{"label":"2 Codes","features":["200 one-time AI credits","200 one-time image/vector/video/audio credits"]},{"label":"3 Codes","features":["300 one-time AI credits","300 one-time image/vector/video/audio credits"]},{"label":"4 Codes","features":["400 one-time AI credits","400 one-time image/vector/video/audio credits"]},{"label":"5+ Codes (up to 10)","features":["Up to 1,000 one-time AI credits","Up to 1,000 one-time image/vector/video/audio credits","Stack unlimited codes"]}]','{"rating":"4.85","count":"557"}','["Access to 330M+ royalty-free images, videos, and music files","AI Image Generator with two model options (Bria for brand-safe visuals; Nano Banana for bold imagery)","AI-powered image editing (object removal, background removal, face modification)","Conversational AI Assistant for integrated search and generation","Over 600 curated collections with 5M+ new files monthly"]',71,'2026-09-15T19:42:42.950Z');
