INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('screentovideo','inventory','ScreenToVideo','','https://screentovideo.com','https://screentovideo.com/wp-content/uploads/2019/06/logo.png','img/screentovideo.png','Video & Audio','ScreenToVideo captures your full screen, an application window, or a chosen area in one click, then lets you enhance recordings with text, zoom effects, sounds, images, and animations. It is a capable all-in-one screen recorder and video editor for tutorials, demos, and walkthroughs. The lifetime-deal license is transferable and the owner welcomes a fair offer, so reach out to inquire.','Record your screen, edit like a pro','https://appsumo.com/products/marketplace-screentovideo/','https://appsumo2-cdn.appsumo.com/media/selfsubmissions/images/84c129f8-7491-4f2e-a78c-dc34adf42efb.png',1,'[{"label":"ScreenToVideo - $59 (50% off regular $119, single tier, not stackable)","features":["One-time payment with lifetime access","Full-featured recorder and editor","Free lifetime upgrades and support","In-app and website support","Windows compatibility","Google Drive integration"]}]','{"rating":"4.69","count":"111"}','["Record, edit, and share your videos with a powerful yet easy-to-use screen recorder","AI-powered virtual backgrounds, silence removal, and blur effects","Built-in captions with text-to-speech integration","Multiple export formats (MP4, WMV, GIF, MP3)","Hardware-accelerated export speed"]',88,'2026-09-15T19:42:42.951Z');
