INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('semdash','inventory','Semdash','','https://semdash.com','https://famyayvemq6ogs8n.public.blob.vercel-storage.com/logos/675267b18dc380d6329a435a7e34af53%20%281%29.webp','img/semdash.webp','SEO','Semdash bundles keyword research, competitor analysis, backlink data, and SERP checking into one AI-assisted workflow so you can find opportunities and rank higher without juggling multiple tools. This is a transferable lifetime-deal license, so you skip the recurring monthly credits and own your access outright. The owner still uses it and is open to a fair offer, so send an inquiry to start the conversation.','All-in-one SEO research and analysis','https://appsumo.com/products/semdash/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-Semdash_-_16_9_uuid_ab2b8749-53b6-434a-9012-78a49cb79ed3.png',1,'[{"label":"Tier 1 ($79)","features":["1,000 credits/month","ChatSEO","Keyword research","Competition analysis","Backlink research","SERP checker","AI SEO","Lead generation"]},{"label":"Tier 2 ($219)","features":["4,000 credits/month","Same 8 features as Tier 1"]},{"label":"Tier 3 ($399)","features":["10,000 credits/month","Same 8 features as Tier 1"]},{"label":"Tier 4 ($509, Recommended)","features":["15,000 credits/month","Same 8 features as Tier 1"]},{"label":"Tier 5 ($589)","features":["20,000 credits/month","Same 8 features as Tier 1"]}]','{"rating":"4.14","count":"125"}','["Analyze client competitors to uncover keywords and content gaps","Access a database of 40M local businesses with contact info","AI-powered ChatSEO tool integrating 27B keywords and 3T backlinks","12 months of ranking history data","White-label SEO report generation"]',89,'2026-09-15T19:42:42.951Z');
