INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('shortpixel','inventory','ShortPixel','','https://shortpixel.com','https://shortpixel.com/img/bighead.jpg','img/shortpixel.jpg','WordPress','ShortPixel optimizes and compresses your images, converting them to modern formats like WebP and AVIF to speed up your site and improve SEO, with seamless WordPress plugins and a developer API. This is a transferable lifetime-deal license, giving you optimization credits without the ongoing subscription. The owner still uses it and would consider a fair offer, so reach out to inquire.','Compress images without losing quality','https://appsumo.com/products/shortpixel/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-ShortPixel_1.jpg',1,'[{"label":"License Tier 1 (1 Code)","features":["Lifetime access","15,000 monthly credits","Up to 125 GB CDN traffic","All features included"]},{"label":"License Tier 2 (2 Codes)","features":["Lifetime access","30,000 monthly credits","Up to 250 GB CDN traffic","All features included"]},{"label":"License Tier 3 (3 Codes)","features":["Lifetime access","45,000 monthly credits","Up to 375 GB CDN traffic","All features included"]}]','{"rating":"4.8","count":"159"}','["Compress image file sizes by up to 90% while maintaining quality","Three compression options: Lossy, Glossy, and Lossless","Two WordPress plugins for automatic optimization","Shopify app and PHP tools available","Images processed on the fly via global CDN"]',90,'2026-09-15T19:42:42.951Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('shortpixel',0,'available','inquire',NULL,'Tier 5 account · 5 codes stacked');
INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('ticket-tailor','inventory','Ticket Tailor','','https://www.tickettailor.com','https://ps.w.org/ticket-tailor/assets/banner-772x250.png','img/ticket-tailor.png','E-commerce','Ticket Tailor is a straightforward event ticketing platform that lets you design event pages, sell tickets, and check in attendees using your own payment provider like Stripe, Square, or PayPal. This is a transferable lifetime-deal license, so you get long-term access without recurring platform fees. The owner still uses it and is open to a fair offer, so send an inquiry if you run events.','Sell event tickets online in minutes','https://appsumo.com/products/ticket-tailor/','https://appsumo2-cdn.appsumo.com/media/deals/images/as-web-TicketTailor.png',1,'[{"label":"Single Tier (not stackable)","features":["1 year of free access","100 tickets per month (non-rolling)","Unlimited events","Additional tickets at standard price + Stripe fees","Plan updates included for 1 year","10% renewal discount in year 2","New users only; redeem within 60 days"]}]','{"rating":"4.5","count":"4"}','["Fully customizable, branded event pages","Seating chart tool for venue events","Support for recurring events with time slots and day passes","Live sales reporting and analytics","Third-party integrations: Mailchimp, Constant Contact, Zapier, Stripe, PayPal"]',91,'2026-09-15T19:42:42.951Z');
