INSERT INTO products (slug,source,name,descr,homepage,image,local_img,category,offer,tagline,appsumo_url,appsumo_image,inquire_only,license_tiers,reviews,highlights,sort,updated_at) VALUES ('voicedash','inventory','VoiceDash','','https://voicedash.ai','https://voicedash.ai/wp-content/uploads/2026/01/VoiceDash-Header-Image.png','img/voicedash.png','Productivity','VoiceDash is an AI voice dictation tool that turns natural speech into clean, punctuated, structured text right where your cursor sits, working across apps on Mac, Windows, iPhone, and Android. It removes filler words, fixes grammar, and supports personal dictionaries and snippet libraries for faster writing. This is a transferable lifetime-deal license and the owner is open to a fair offer, so reach out to inquire.','Turn speech into polished writing instantly','https://appsumo.com/products/voicedash/','https://appsumo2-cdn.appsumo.com/media/deals/images/voicedash-as-Header-VoiceDash-16_9.png',1,'[{"label":"License Tier 1 ($59)","features":["Lifetime access","1 team member","200,000 words/month","Unlimited devices","Personal dictionary","Snippet library","Advanced AI editing","Zero data retention option"]},{"label":"License Tier 2 ($149)","features":["Lifetime access","3 team members","600,000 words/month","Unlimited devices","All Tier 1 features","Words pooling","Shared snippet library"]},{"label":"License Tier 3 ($299)","features":["Lifetime access","7 team members","1,400,000 words/month","Unlimited devices","All Tier 2 features"]},{"label":"License Tier 4 ($499)","features":["Lifetime access","15 team members","3,000,000 words/month","Unlimited devices","All Tier 3 features"]}]','{"rating":"4.43","count":"233"}','["Converts speech to polished text across Mac, Windows, Linux, Android, iOS","Removes filler words and corrects grammar in real time","Works system-wide in any application","Supports 50+ languages","Zero Data Retention (ZDR) privacy standard"]',92,'2026-09-15T19:42:42.951Z');
INSERT INTO units (slug,idx,status,price_kind,price,account) VALUES ('voicedash',0,'available','inquire',NULL,'Tier 2 account');
